package org.com.sharekhan.analysis;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import com.fasterxml.jackson.databind.ObjectMapper;
import java.nio.file.*;import java.time.*;import java.util.*;import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import static org.com.sharekhan.analysis.ThesisModels.*;
class ThesisServiceTest {
 @TempDir Path dir;final Clock clock=Clock.fixed(Instant.parse("2026-11-02T10:00:00Z"),StockAnalysisService.IST);ThesisStore store;SavedDailyAnalysis daily;FluencySnapshotStore sources;ThesisService service;
 @BeforeEach void init(){store=new ThesisStore(new ObjectMapper().findAndRegisterModules(),dir.toString());daily=mock(SavedDailyAnalysis.class);sources=mock(FluencySnapshotStore.class);when(daily.members()).thenReturn(List.of(new StockDailyHistoryStore.Member("RELIANCE","INE1",LocalDate.of(2026,11,1)),new StockDailyHistoryStore.Member("TCS","INE2",LocalDate.of(2026,11,1))));when(sources.load()).thenReturn(List.of());service=new ThesisService(store,daily,sources,clock);}
 Create draft(String id){return new Create(id,"RELIANCE","GROWTH_MOMENTUM","","Research thesis from observed chart","Wait for the reviewed setup","Invalidate if structure breaks",LocalDate.of(2026,11,9));}
 Entry create(){return service.create("USER:1",draft(UUID.randomUUID().toString()));}
 @Test void privateEmptyReadsCreateNoFiles()throws Exception{assertThat(service.book("USER:1").entries()).isEmpty();try(var files=Files.list(dir)){assertThat(files.count()).isZero();}}
 @Test void manualThesisIsResearchOnlyAndStartsAtIdea(){var e=create();assertThat(e.kind()).isEqualTo("RESEARCH_THESIS");assertThat(e.state()).isEqualTo("IDEA");assertThat(e.revision()).isEqualTo(1);assertThat(e.source().origin()).isEqualTo("MANUAL_RESEARCH");assertThat(service.get("USER:1",e.id())).isEqualTo(e);assertThat(service.book("USER:1").entries()).hasSize(1);verify(sources,never()).save(any());}
 @Test void accountAndAdminCannotReadAnotherOwnersRecord(){var e=create();for(var owner:List.of("USER:2","ADMIN:1")){assertThat(service.book(owner).entries()).isEmpty();assertThatThrownBy(()->service.get(owner,e.id())).isInstanceOf(org.springframework.web.server.ResponseStatusException.class).hasMessageContaining("404");}var own=service.create("USER:2",draft(e.id()));assertThat(own.id()).isEqualTo(e.id());assertThat(service.book("USER:1").entries()).hasSize(1);assertThat(service.book("USER:2").entries()).hasSize(1);}
 @Test void createRetriesAreIdempotentAndNeverOverwriteLaterEdits(){var id=UUID.randomUUID().toString();var d=draft(id);var e=service.create("USER:1",d);assertThat(service.create("USER:1",d)).isEqualTo(e);var updated=service.amend("USER:1",id,new Amend(1,"New thesis with revised chart evidence",e.entryCondition(),e.invalidation(),e.nextReview(),"Chart changed"));assertThat(service.create("USER:1",d)).isEqualTo(updated);var conflict=new Create(id,"TCS",d.thesisType(),"",d.thesis(),d.entryCondition(),d.invalidation(),d.nextReview());assertThatThrownBy(()->service.create("USER:1",conflict)).hasMessageContaining("409");}
 @Test void amendmentsKeepOriginalTextAndRejectStaleRevisions(){var e=create();var next=service.amend("USER:1",e.id(),new Amend(1,"Revised thesis after chart review",e.entryCondition(),e.invalidation(),e.nextReview(),"Updated context"));assertThat(next.history().getFirst().thesis()).isEqualTo(e.thesis());assertThat(next.history().getLast().thesis()).isEqualTo(next.thesis());assertThatThrownBy(()->service.amend("USER:1",e.id(),new Amend(1,e.thesis(),e.entryCondition(),e.invalidation(),e.nextReview(),"Stale edit"))).hasMessageContaining("409");assertThat(service.get("USER:1",e.id()).revision()).isEqualTo(2);}
 @Test void forwardLifecycleClosureAndPostmortemNeverClaimAFill(){var e=create();String id=e.id();assertThatThrownBy(()->service.transition("USER:1",id,new Transition(1,"ACTIVE","Not a broker fill",null,null))).hasMessageContaining("409");e=service.transition("USER:1",id,new Transition(1,"ENTRY_READY","Chart review complete",null,null));e=service.transition("USER:1",id,new Transition(2,"TRACKING","Follow the research thesis",null,null));assertThatThrownBy(()->service.transition("USER:1",id,new Transition(3,"CLOSED","Review completed",null,null))).hasMessageContaining("400");e=service.transition("USER:1",id,new Transition(3,"CLOSED","Study finished","Setup faded after observation","Wait for better confirmation"));assertThat(e.state()).isEqualTo("CLOSED");assertThatThrownBy(()->service.transition("USER:1",id,new Transition(4,"TRACKING","Reopen",null,null))).hasMessageContaining("409");assertThatThrownBy(()->service.amend("USER:1",id,new Amend(4,"Cannot silently rewrite terminal thesis", "Entry","Invalidation",LocalDate.of(2026,11,9),"Wrong"))).hasMessageContaining("409");e=service.postmortem("USER:1",id,new Postmortem(4,"A detailed observation about why the thesis failed."));assertThat(e.revision()).isEqualTo(5);assertThat(e.history().getLast().action()).isEqualTo("POSTMORTEM");assertThat(e.outcome()).isEqualTo("Setup faded after observation");}
 @Test void invalidationRequiresOutcomeAndLessonsAndIsTerminal(){var e=create();var next=service.transition("USER:1",e.id(),new Transition(1,"INVALIDATED","Research thesis disproved","Support was lost","Review invalidation first"));assertThat(next.state()).isEqualTo("INVALIDATED");assertThat(service.book("USER:1").dueCount()).isZero();assertThatThrownBy(()->service.review("USER:1",e.id(),new Review(2,"OK",null,"Review"))).hasMessageContaining("409");}
 @Test void reviewsUseServerDatesAndRemainDueUntilRescheduled(){var e=create();service.review("USER:1",e.id(),new Review(1,"WARN",LocalDate.of(2026,11,2),"Needs further chart review"));assertThat(service.book("USER:1").dueCount()).isEqualTo(1);var next=service.review("USER:1",e.id(),new Review(2,"OK",LocalDate.of(2026,11,10),"Review completed with updated conditions"));assertThat(service.book("USER:1").dueCount()).isZero();assertThat(next.history()).hasSize(3);assertThatThrownBy(()->service.review("USER:1",e.id(),new Review(3,"AUTO_BUY",null,"Invalid review"))).hasMessageContaining("400");}
 @Test void sourceProvenanceIsFrozenAndCannotBeForgedToAnotherSymbol(){var c=new FluencyService.Candidate("source1","RELIANCE","10",LocalDate.of(2026,10,30),80,List.of("RANGE_EXPANSION"),List.of(),100,95,"a".repeat(64),clock.instant(),false);var s=new FluencyService.Snapshot(FluencyService.VERSION,c.setupDate(),clock.instant(),LocalDate.of(2026,11,1),"SAVED_ARCHIVE_RECONSTRUCTION","MARKET_CAUTION",200,197,.2,List.of(c));when(sources.load()).thenReturn(List.of(s));var d=draft(UUID.randomUUID().toString());var e=service.create("USER:1",new Create(d.requestId(),d.symbol(),d.thesisType(),"source1",d.thesis(),d.entryCondition(),d.invalidation(),d.nextReview()));assertThat(e.source().rawCandidate()).isEqualTo(c);assertThat(e.source().marketGate()).isEqualTo("MARKET_CAUTION");when(sources.load()).thenReturn(List.of());assertThat(service.get("USER:1",e.id()).source().rawCandidate()).isEqualTo(c);when(sources.load()).thenReturn(List.of(s));assertThatThrownBy(()->service.create("USER:1",new Create(UUID.randomUUID().toString(),"TCS",d.thesisType(),"source1",d.thesis(),d.entryCondition(),d.invalidation(),d.nextReview()))).hasMessageContaining("400");}
 @Test void invalidInputsAndPathTraversalCannotCreateFiles(){var d=draft(UUID.randomUUID().toString());assertThatThrownBy(()->service.get("USER:1","../../etc/passwd")).hasMessageContaining("400");assertThatThrownBy(()->service.create("USER:1",new Create(d.requestId(),"UNSUPPORTED",d.thesisType(),"",d.thesis(),d.entryCondition(),d.invalidation(),d.nextReview()))).hasMessageContaining("400");assertThatThrownBy(()->service.create("USER:1",new Create(d.requestId(),d.symbol(),d.thesisType(),"","short",d.entryCondition(),d.invalidation(),d.nextReview()))).hasMessageContaining("400");assertThat(service.book("USER:1").entries()).isEmpty();}
 @Test void competingEditsAcrossStoreInstancesPublishOnlyOneRevision()throws Exception{var e=create();var second=new ThesisService(new ThesisStore(new ObjectMapper().findAndRegisterModules(),dir.toString()),daily,sources,clock);var gate=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){var tasks=new ArrayList<Future<Boolean>>();for(var svc:List.of(service,second))tasks.add(pool.submit(()->{gate.await();try{svc.amend("USER:1",e.id(),new Amend(1,"Concurrent thesis amendment with evidence",e.entryCondition(),e.invalidation(),e.nextReview(),"Concurrent edit"));return true;}catch(org.springframework.web.server.ResponseStatusException conflict){assertThat(conflict.getStatusCode().value()).isEqualTo(409);return false;}}));gate.countDown();int wins=0;for(var f:tasks)if(f.get())wins++;assertThat(wins).isEqualTo(1);}assertThat(service.get("USER:1",e.id()).revision()).isEqualTo(2);}
 @Test void missingOrCorruptRevisionsFailInsteadOfResettingHistory()throws Exception{var e=create();var folder=dir.resolve(VERSION).resolve(StockDailyHistoryStore.digest("USER:1")).resolve(e.id());Files.writeString(folder.resolve("000002.json"),"{}");assertThatThrownBy(()->service.get("USER:1",e.id())).isInstanceOf(IllegalStateException.class);assertThat(Files.readString(folder.resolve("000001.json"))).contains(e.id());}
}
